        sources: ['Anthropic, "Building effective agents" (December 2024)', 'Framework documentation: LangGraph, OpenAI Agents SDK, Claude Agent SDK, CrewAI, Microsoft Agent Framework, Pydantic AI (accessed October 2026)'],
