      ex: { prompt: 'Write scoreFramework(frameworks, weights) where frameworks are { name, scores } and weights map criteria to numbers. Each framework\'s score is the weighted average Σ(score × weight) / Σweights (missing scores count as 0), rounded to 2 decimals. Return [{ name, score }] sorted by score descending, ties by name ascending.', fn: 'scoreFramework', params: 'frameworks, weights', cases: [{ args: [[{ name: 'no-framework', scores: { control: 5, durability: 2, ecosystem: 2, learning: 5 } }, { name: 'langgraph', scores: { control: 4, durability: 5, ecosystem: 4, learning: 2 } }, { name: 'agents-sdk', scores: { control: 3, durability: 3, ecosystem: 4, learning: 4 } }], { control: 3, durability: 3, ecosystem: 1, learning: 1 }], expect: [{ name: 'langgraph', score: 4.13 }, { name: 'no-framework', score: 3.5 }, { name: 'agents-sdk', score: 3.25 }] }], solution: `function scoreFramework(fs,w){const total=Object.values(w).reduce((a,b)=>a+b,0);return fs.map(f=>({name:f.name,score:Math.round(Object.entries(w).reduce((s,[c,x])=>s+(f.scores[c]||0)*x,0)/total*100)/100})).sort((a,b)=>(b.score-a.score)||(a.name<b.name?-1:1))}`, hint: 'Weighted sum divided by total weight, then sort.' },
