      tip: "Write your eval suite against your own Runner interface on day one; it becomes the migration safety net you will be glad of later.",
      faq: [['What is a thin core?', 'Small internal interfaces (ports) with adapters to frameworks or SDKs.'], ['Which ports matter most?', 'Model client, tool registry, runner, state store, and trace sink.'], ['How do you migrate safely?', 'Run the same eval suite on old and new runners, then shift traffic gradually.'], ['Are concept maps exact?', 'No; equivalents differ in semantics, so document differences.'], ['What is the risk of a thin core?', 'It can grow into a home-grown framework if not kept minimal.']],
      ex: { prompt: 'Write mapConcept(term, from, to, table) where table is a list of rows mapping framework keys (such as "plain", "langgraph", "openai", "claude") to terms. Find the first row whose value for from equals term and return its value for to, or null if no row matches or the row has no entry for to.', fn: 'mapConcept', params: 'term, from, to, table', cases: [{ args: ['handoff', 'openai', 'claude', [{ plain: 'delegation', langgraph: 'subgraph', openai: 'handoff', claude: 'subagent' }, { plain: 'human approval', langgraph: 'interrupt', claude: 'permission prompt' }, { plain: 'saved state', langgraph: 'checkpoint', openai: 'session', claude: 'session' }]], expect: 'subagent' }, { args: ['interrupt', 'langgraph', 'plain', [{ plain: 'human approval', langgraph: 'interrupt', claude: 'permission prompt' }]], expect: 'human approval' }, { args: ['interrupt', 'langgraph', 'openai', [{ plain: 'human approval', langgraph: 'interrupt', claude: 'permission prompt' }]], expect: null }, { args: ['crew', 'crewai', 'plain', [{ plain: 'delegation', openai: 'handoff' }]], expect: null }], solution: `function mapConcept(term,from,to,table){const row=table.find(r=>r[from]===term);return row&&row[to]!==undefined?row[to]:null}`, hint: 'find() the row, then read the target key.' },
